def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    divider=next(c for c in range(w) if all(g[r][c]==5 for r in range(h)))
    seen=set(); comps=[]
    for r in range(h):
        for c in range(divider):
            if g[r][c]==0 and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c)); comp=[]
                while stack:
                    a,b=stack.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<divider and g[x][y]==0 and (x,y) not in seen:
                            seen.add((x,y)); stack.append((x,y))
                comps.append(comp)
    for comp in comps:
        shift=divider-1-max(c for r,c in comp)
        for r,c in comp: g[r][c]=6
        for r,c in comp: g[r][c+shift]=0
    for r in range(h):
        if g[r][divider-3:divider]==[0,6,0]:
            for c in range(divider+1,w): g[r][c]=2
    return g

